set owner_id = (select id from public.accounts where username = 'petani01')
where owner_id is null;

-- ===== SELESAI =====
select
  'Setup Tani Loa Lepu selesai!' as status,
  (select count(*) from public.accounts) as jumlah_akun,
  (select count(*) from public.crops) as jumlah_tanaman,
  (select count(*) from public.products) as jumlah_produk,
  (select count(*) from public.lands) as jumlah_lahan;

-- ===== KATALOG TANAMAN (GELOMBANG 2: sayur, buah & bumbu dapur) =====
-- 20 tanaman baru: 8 sayuran, 4 buah, 8 bumbu dapur (idempoten)
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('bayam', 'Bayam', 'Amaranthus tricolor', 'sayuran', 'mudah', 25, 'banyak', 'terang', 'Sepanjang tahun', 'Bayam adalah sayuran daun paling populer sehari-hari masyarakat Indonesia, kaya zat besi, protein, dan vitamin A. Tanaman ini tumbuh sangat cepat — bisa dipanen hanya 20–30 hari setelah semai — sehingga ideal untuk menopang kas petani karena siklus uang kembali segera. Bayam cocok ditanam di pekarangan rumah, polybag, maupun lahan luas, dan permintaan pasarnya tidak pernah turun karena menjadi menu masakan harian seperti bening, pecel, hingga tahu isi.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3bbec5e00d8b.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3bbec5e00d8b.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/880b10701570.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/25f1ec3d81a8.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/798dfe8b79c0.jpg"]', '["Olah tanah ringan dengan cangkul hingga gembur, campurkan pupuk kandang matang, buat bedengan lebar 100–120 cm.", "Taburkan benih secara merata (broadcast) di permukaan bedengan, tutup tipis dengan tanah halus atau sekam bakar.", "Siram 2 kali sehari pagi dan sore, jaga tanah selalu lembap hingga berkecambah 3–5 hari.", "Panen pada usia 20–30 hari dengan mencabut seluruh tanaman atau memotong 3 ruas dari pangkal agar tumbuh kembali."]', '["Pilih varietas hijau (bayam hijau) untuk pasar umum dan bayam cabut merah untuk khas pasar sayur premium.", "Beri pupuk organik cair atau urea dosis kecil setiap 7–10 hari agar daun lebat dan hijau segar.", "Tanam bertahap setiap minggu di petak berbeda supaya panen berkelanjutan setiap pekan.", "Awas ulat daun; gunakan perangkap kuning dan pestisida nabati ekstrak daun mimba bila serangan mulai ramai."]', '[{"name": "Ulat Daun (Spodoptera)", "symptom": "Daun berlubang dan hanya tersisa tulang daun; ditemukan larva hijau-cokelat.", "treatment": "Rakit larva secara manual, semprotkan Bt (Bacillus thuringiensis) atau ekstrak mimba."}, {"name": "Busuk Akar", "symptom": "Tanaman layu mendadak, akar kehitaman dan berbau tidak sedap.", "treatment": "Perbaiki drainase bedengan, kurangi frekuensi siram, aplikasikan Trichoderma."}, {"name": "Bercak Daun Cercospora", "symptom": "Bercak kecil cokelat muda dengan tepi gelap tersebar di daun.", "treatment": "Jaga jarak tanam agar sirkulasi baik, semprotkan fungisida berbahan tembaga bila berat."}]', 'Rp 4.000 – 8.000 / ikat')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('sawi', 'Sawi Hijau', 'Brassica juncea', 'sayuran', 'mudah', 45, 'sedang', 'terang', 'Sepanjang tahun, terbaik musim kemarau', 'Sawi hijau adalah sayuran keluarga kubis yang cepat panen dan digemari pasar karena rasa gurih khasnya. Cocok untuk tumisan, sayur asem, hingga asinan, permintaannya stabil di pasar tradisional dan rumah makan. Sawi termasuk tanaman perawatan mudah — tahan panas lebih baik daripada kol — dan cocok ditanam bergantian dengan kangkung atau bayam untuk memutar pasokan sayur harian petani.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b85b234a4c05.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b85b234a4c05.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/3d81acbda818.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ecb4f2fed1be.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/1968b6a97753.jpg"]', '["Semai benih di tray atau bedengan persemaian selama 2–3 minggu hingga berdaun 4–5 helai.", "Olah bedengan tinggi 25–30 cm dan beri pupuk kandang matang 10–15 ton/ha sebagai dasar.", "Tanam bibit dengan jarak 25×30 cm, segera siram larutan agens hayati untuk mencegah layu.", "Panen pada usia 40–50 hari saat daun sudah lebat sebelum tanaman mulai berbunga."]', '["Siram rutin pagi hari; hindari genangan karena akar sawi mudah busuk.", "Pemupukan susulan urea dua kali: usia 14 dan 28 hari setelah tanam untuk daun tebal hijau.", "Pasang perangkap kuning untuk mengendalikan kutu daun dan lalat putih secara hayati.", "Panen sore hari dengan memotong pangkal batang, kumpulkan di tempat teduh agar tetap segar."]', '[{"name": "Kutu Daun (Lipaphis)", "symptom": "Koloni serangga hijau kecil di balik daun muda; daun keriting menguning.", "treatment": "Semprotkan sabun kalium atau insektisida nabati, pasang perangkap kuning."}, {"name": "Busuk Lunak", "symptom": "Pangkal batang membusuk berair dan berbau menyengat saat musim hujan.", "treatment": "Perbaiki drainase, hindari kepadatan tanam, cabut tanaman sakit segera."}, {"name": "Bercak Daun Alternaria", "symptom": "Bercak cokelat gelap dengan lingkaran konsentris pada daun tua.", "treatment": "Buang daun terinfeksi, semprotkan fungisida berbahan aktif klorotalonil."}]', 'Rp 5.000 – 10.000 / ikat')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('wortel', 'Wortel', 'Daucus carota', 'sayuran', 'sedang', 95, 'sedang', 'terang penuh', 'Musim kemarau di dataran tinggi', 'Wortel adalah umbi akar bernilai jual tinggi yang kaya beta-karoten, digemari untuk sup, jus, hingga bumbu masakan. Budidaya wortel paling berhasil di dataran tinggi dengan tanah gembur, remah, dan bebas batu agar umbi tumbuh lurus panjang. Meski memerlukan perawatan lebih teliti dibanding sayuran daun, harga wortel cenderung stabil dan pasokan dari petani lokal masih jauh dari mencukupi kebutuhan pasar.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c97f6552165b.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c97f6552165b.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/37ebe2dccc45.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4030a83b71f0.jpeg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b5ed1ebb0462.jpg"]', '["Olah tanah sedalam 25–30 cm hingga sangat gembur, buang batu dan sisa akar, buat guludan tinggi 30 cm.", "Taburkan benih di alur dangkal berjarak 20 cm, tutup tipis dengan tanah halus dan mulsa jerami tipis.", "Jaga kelembapan dengan penyiraman halus setiap hari hingga berkecambah 7–14 hari.", "Jarangkan bibit (thinning) saat berdaun 3–4 helai, sisakan tanaman terkuat setiap 7–8 cm."]', '["Gunakan tanah lempar berpasir yang lewat saringan; tanah berbatu membuat umbi bercabang-cabang.", "Pupuk dasar dominan kalium dan fosfor untuk pembentukan umbi; kurangi nitrogen berlebih.", "Rajin penyiangan gulma karena pertumbuhan awal wortel lambat dan mudah kalah bersaing.", "Panen saat daun mulai menguning (usia 90–100 hari); gali hati-hati agar umbi tidak patah."]', '[{"name": "Lalat Wortel (Psila rosae)", "symptom": "Terowongan berliku cokelat di permukaan umbi.", "treatment": "Pasang kelambu halus, lakukan rotasi tanaman, gunakan perangkap lengket kuning."}, {"name": "Busuk Hitam Alternaria", "symptom": "Bercak hitam di daun dan kepala umbi saat lembap terus.", "treatment": "Jaga sirkulasi udara, semprotkan fungisida, panen jangan terlambat."}, {"name": "Ubi Membelah", "symptom": "Umbi retak akibat air tidak teratur — kering lalu hujan deras.", "treatment": "Jaga kelembapan tanah merata dengan mulsa dan penyiraman terjadwal."}]', 'Rp 8.000 – 15.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('terung', 'Terung Ungu', 'Solanum melongena', 'sayuran', 'sedang', 75, 'sedang', 'terang penuh', 'Sepanjang tahun', 'Terung ungu adalah sayuran buah andalan yang dipanen bertahap selama 3–4 bulan sehingga memberi penghasilan mingguan bagi petani. Digemari untuk semua jenis masakan — dari tumis, gulai, terong balado hingga sambal goreng — pasarnya luas dari rumah tangga hingga restoran. Dengan pemupukan rutin dan pengendalian hama yang disiplin, satu tanaman terung bisa menghasilkan 20–40 buah sepanjang masa panen.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ed171b722590.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ed171b722590.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0101eaec8ed9.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/f31888fd4b36.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/043102fb7fbe.jpg"]', '["Semai benih di tray semai 3–4 minggu hingga bibit berdaun 4–6 helai dan batang kokoh.", "Olah bedengan 30–40 cm dengan pupuk kandang matang, beri mulsa plastik hitam perak.", "Tanam dengan jarak 60×70 cm, sore hari; siram segera dan pasang ajir penyangga.", "Panen buah pertama pada usia 65–75 hari saat kulit masih mengkilap, potong dengan gunting beserta pangkalnya."]', '["Panen setiap 4–5 hari sekali agar tanaman terus berbuah dan buah tidak tua berbiji besar.", "Pupuk NPK susulan setiap 10 hari; tambahkan kalium saat fase berbuah lebat.", "Pangkas tunas bawah dan daun tua agar sirkulasi udara baik dan hama terlihat jelas.", "Kendalikan pengorok daun dan kutu daun dengan perangkap kuning serta pestisida nabati."]', '[{"name": "Pengorok Daun (Liriomyza)", "symptom": "Pola garis putih berliku seperti peta di permukaan daun.", "treatment": "Buang dan bakar daun sakit, pasang perangkap kuning, semprotkan insektisida hayati."}, {"name": "Layu Bakteri", "symptom": "Tanaman layu cepat di siang hari tanpa daun menguning; batang berlubang cokelat.", "treatment": "Rotasi tanaman, aplikasi agens hayati Trichoderma, cabut tanaman parah."}, {"name": "Antraknosa Buah", "symptom": "Bercak cekung cokelat gelap pada buah tua saat musim hujan.", "treatment": "Panen tepat waktu, semprotkan fungisida tembaga, hindari kepadatan tanam."}]', 'Rp 8.000 – 18.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kacang-panjang', 'Kacang Panjang', 'Vigna unguiculata sesquipedalis', 'sayuran', 'mudah', 60, 'sedang', 'terang penuh', 'Sepanjang tahun, hindari puncak hujan', 'Kacang panjang adalah sayuran polong rakyat yang mudah dibudidayakan di semua jenis lahan, termasuk pekarangan sempit. Sebagai tanaman kacang-kacangan, ia juga memperbaiki kesuburan tanah dengan mengikat nitrogen sehingga cocok sebagai tanaman rotasi. Panen dilakukan setiap 2–3 hari selama 1–2 bulan, menjadikannya sumber penghasilan rutin untuk kebutuhan dapur sekeluarga maupun pasar harian.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/859527ea992f.png', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/859527ea992f.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c794d8ae96de.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/77c4e7da4549.png", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/eb7f776a14eb.jpg"]', '["Olah tanah ringan, buat lubang tanam jarak 50×50 cm, beri pupuk kandang dasar per lubang.", "Tanam 2–3 benih per lubang kedalaman 2–3 cm, basahi dengan air secukupnya.", "Pasang ajir/gulungan kawat saat tanaman berumur 10 hari untuk memanjat.", "Panen polong muda setiap 2–3 hari saat panjang 40–50 cm dan masih lembut."]', '["Panen terlambat membuat polong keras berbiji dan tanaman berhenti berbunga — disiplinkan jadwal panen.", "Pemupukan urea tipis di awal tumbuh, lalu cukup pupuk organik karena akarnya mengikat nitrogen sendiri.", "Awas hama penghisap polong dan lalat kacang; gunakan perangkap dan semprotan nabati rutin.", "Potong polong dengan gunting atau putih tangan hati-hati agar cabang produksi tidak patah."]', '[{"name": "Lalat Kacang (Ophiomyia)", "symptom": "Daun menggulung dan tunas layu karena larva menggerek pangkal batang.", "treatment": "Perangkap feromon kuning, musnahkan sisa tanaman terinfeksi, rotasi tanaman."}, {"name": "Kutu Kepul", "symptom": "Sekelompok serangga putih menempel di pucuk dan polong muda.", "treatment": "Semprotkan sabun kalium atau ekstrak bawang putih, jagung (trap crop) di sekeliling."}, {"name": "Karat Daun", "symptom": "Bintik kecokelatan seperti karat di daun bawah.", "treatment": "Jaga jarak tanam, fungisida tembaga, buang daun sakit."}]', 'Rp 8.000 – 15.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('timun', 'Timun', 'Cucumis sativus', 'sayuran', 'mudah', 45, 'banyak', 'terang', 'Musim kemarau dengan irigasi cukup', 'Timun adalah sayuran buah yang sangat cepat panen — hanya 40–50 hari dari semai — dengan permintaan tinggi untuk lalapan, rujak, acar, dan jus. Tanaman merambat ini produktif dan bisa dipanen setiap 1–2 hari selama sebulan lebih. Timun cocok ditanam di musim kemarau dengan irigasi cukup karena harga sayuran justru naik saat pasokan menipis, memberi keuntungan lebih bagi petani yang siap air.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/70a4b0388073.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/70a4b0388073.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9c2d1bc557e9.jpeg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/874741915018.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4246214d94cc.jpg"]', '["Buat guludan/bedengan dengan mulsa plastik, tanam 2 benih per lubang jarak 50×60 cm.", "Basahi lubang sebelum menanam, tutup benih tipis; berkecambah dalam 3–5 hari.", "Pasang patok dan tali rafia untuk merambatkan tanaman atau biarkan merambat di mulsa.", "Panen buah muda setiap 1–2 hari saat panjang 15–20 cm, kulit hijau mengilap sebelum menguning."]', '["Siram secara teratur — timun 90% air; kekurangan air membuat buah pahit dan keriting.", "Pupuk susulan NPK mingguan mulai usia 14 hari untuk buah terus-menerus.", "Panen pagi hari dengan gunting tajam, sisakan tangkai 1 cm agar tahan segar.", "Kendalikan kutu daun dan trips dengan perangkap kuning dan semprotan sabun nabati."]', '[{"name": "Karat Daun", "symptom": "Bercak kuning-oranye bubuk di permukaan daun menyebar cepat.", "treatment": "Fungisida belerang, jaga sirkulasi, hindari siram sore yang membuat daun basah semalaman."}, {"name": "Layu Fusarium", "symptom": "Tanaman layu perlahan mulai satu sisi lalu mati.", "treatment": "Rotasi tanaman, aplikasi Trichoderma ke bedengan sebelum tanam."}, {"name": "Ulat Daun", "symptom": "Daun berlubang; ditemukan larva hijau dengan kepala gelap.", "treatment": "Rakit manual, semprotkan Bt saat populasi meningkat."}]', 'Rp 6.000 – 12.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kol', 'Kol / Kubis', 'Brassica oleracea var. capitata', 'sayuran', 'sedang', 90, 'sedang', 'terang', 'Musim kemarau di dataran tinggi', 'Kol (kubis) adalah sayuran berbentuk bola padat yang selalu dibutuhkan pasar rumah tangga, warung makan, hingga industri katering. Cocok tumbuh di dataran tinggi yang sejuk dengan tanah subur dan drainase baik. Harga kol cukup stabil dan hasil simpannya lebih tahan lama dibanding sayuran daun lain, sehingga risiko kerugian pasca panen lebih kecil bagi petani.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/800937dd9808.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/800937dd9808.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/7348adc9f3ab.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c5e38e5ad0c7.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/958fce8477fa.jpg"]', '["Semai benih di persemaian 3–4 minggu, pilih bibit sehat berdaun 5–6 helai untuk pindah tanam.", "Olah bedengan lebar 100 cm dengan pupuk kandang 20 ton/ha dan dolomit bila tanah masam.", "Tanam jarak 50×50 cm, tekan tanah di pangkal bibit agar kokoh, siram larutan hayati.", "Panen saat kepala kol padat dan kenyal (usia 80–95 hari), potong beserta 2–3 daun pelindung."]', '["Jaga kelembapan merata; kurang air membuat kepala kol pecah dan tidak padat.", "Pemupukan bertahap: nitrogen di awal tumbuh, kalium dan fosfor saat kepala mulai terbentuk.", "Amati penggerek kubis (ular kubis) — rakit telurnya yang menempel di balik daun setiap pagi.", "Putar (rotasi) lahan dengan tanaman non-brassica setiap musim untuk memutus siklus penyakit tanah."]', '[{"name": "Ular Kubis (Crocidolomia)", "symptom": "Larva bergerombol merusak kepala kol dari dalam; kotoran menempel di lipatan daun.", "treatment": "Rakit telur dan larva, semprotkan Bt atau insektisida hayati neem."}, {"name": "Busuk Lunak Erwinia", "symptom": "Kepala kol membusuk berair dan berbau busuk saat musim hujan.", "treatment": "Perbaiki drainase, hindari luka saat panen, tanam di musim kering."}, {"name": "Keriput Daun (Downy Mildew)", "symptom": "Bercak kuning di atas daun dengan lapisan putih keabu-abuan di baliknya.", "treatment": "Fungisida sistemik, jaga jarak tanam dan sirkulasi udara."}]', 'Rp 6.000 – 12.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('buncis', 'Buncis', 'Phaseolus vulgaris', 'sayuran', 'mudah', 60, 'sedang', 'terang', 'Sepanjang tahun di dataran sedang–tinggi', 'Buncis adalah sayuran polong hijau yang digemari untuk tumisan, sup, hingga sautéing restoran. Panen pertama mulai usia 55–60 hari dan berlanjut setiap 2–3 hari selama 3–4 minggu. Buncis bernilai jual lebih tinggi daripada kacang panjang dan diminati pasar modern (swalayan) karena tampilannya menarik dan tahan simpan, cocok bagi petani yang ingin masuk ke pasar ritel.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4a647d14a96e.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4a647d14a96e.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ba895ec02574.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/44da1eaf380c.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c4847bdd198d.jpg"]', '["Olah tanah hingga gembur, buat guludan dengan jarak antar baris 40–50 cm.", "Tanam benih 2–3 butir per lubang kedalaman 3 cm, jarak antar lubang 15 cm.", "Untuk varietas merambat, siapkan ajir sejak awal; varietas semak (erect) tidak perlu penyangga.", "Panen polong muda saat masih renyah dan biji di dalamnya belum menonjol, tiap 2–3 hari."]', '["Hindari menyiram saat bunga mekar pagi hari agar pembuahan optimal.", "Pupuk dasar kandang; susulan ringan saja karena kacang-kacangan mengikat nitrogen sendiri.", "Panen dengan memegang pangkal polong dan mematahkan perlahan agar cabang tidak rusak.", "Sortir panen: polong lurus segar untuk swalayan, polong patah untuk pasar tradisional."]', '[{"name": "Bercak Karat Uromyces", "symptom": "Bintik kemerahan seperti karat di kedua sisi daun, daun cepat gugur.", "treatment": "Fungisida tembaga/belerang dan hindari kelembapan berlebih di malam hari."}, {"name": "Lalat Kacang", "symptom": "Bibit layu dan mati muda karena larva menggerek pangkal batang.", "treatment": "Perendaman benih insektisida hayati, tanam benih yang sehat dan unggul."}, {"name": "Mosaik Virus", "symptom": "Daun belang kuning-hijau mosaik, tanaman kerdil.", "treatment": "Gunakan benih sehat, kendalikan kutu daun vektor, cabut tanaman sakit."}]', 'Rp 12.000 – 25.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('pisang', 'Pisang', 'Musa paradisiaca', 'buah', 'mudah', 330, 'sedang', 'terang', 'Sepanjang tahun', 'Pisang adalah buah tropis paling dekat dengan kebutuhan masyarakat — dimakan langsung, diolah jadi keripik, sale, hingga seblak, dan dipakai hampir di semua acara adat. Tanaman ini sangat mudah dirawat, diperbanyak dari anakan tanpa biaya bibit besar, dan bisa dipanen sepanjang tahun karena setiap clump berproduksi bergiliran. Sekelompok kebun pisang 20 pohon sudah cukup memberi penghasilan rutin setiap 2–3 minggu bagi keluarga petani.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bbf771241776.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bbf771241776.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bd320d3eec74.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/9ef417a6dc90.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b46d6ba01476.jpg"]', '["Pilih anakan (sucker) sehat berdaun 4–5 helai dari induk produktif, pisahkan dengan sebagian rimpang.", "Buat lubang 60×60×60 cm, campurkan tanah galian dengan pupuk kandang matang.", "Tanam anakan tegak dengan pangkal rimpang terbenam 10–15 cm, padatkan tanah di sekelilingnya.", "Panen tandan saat buah bulat penuh dan sudutnya mulai membulat (umur ±10–11 bulan), potong tangkai dengan parang bersih."]', '["Sisakan 5–7 tanaman induk per clump; buang anakan berlebih agar nutrisi terpusat.", "Berikan pupuk kandang dan abu gosok setiap 2–3 bulan untuk tandan besar dan manis.", "Bungkus tandan muda dengan kantong plastik berpori atau daun agar buah bersih bebas luka lalat buah.", "Pasang penyangga bambu saat tandan muncul agar batang tidak roboh tertiup angin."]', '[{"name": "Lalat Buah", "symptom": "Buah berlubang kecil dan membusuk dari dalam saat hampir matang.", "treatment": "Bungkus tandan, pasang perangkap metil eugenol, segera panen buah matang."}, {"name": "Penyakit Layu Panama", "symptom": "Daun menguning dari bawah lalu mengering; batang dalam berwarna cokelat.", "treatment": "Gunakan bibit tahan penyakit, isolasi dan musnahkan tanaman sakit beserta rimpangnya."}, {"name": "Ulat Penggulung Daun", "symptom": "Daun menggulung dan berlubang oleh larva yang bersembunyi di dalam gulungan.", "treatment": "Buka dan rakit larvanya, semprotkan Bt atau ekstrak nimba."}]', 'Rp 15.000 – 30.000 / tandan')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('pepaya', 'Pepaya', 'Carica papaya', 'buah', 'mudah', 270, 'sedang', 'terang penuh', 'Sepanjang tahun', 'Pepaya adalah buah ekonomi rumah tangga yang cepat berbuah — mulai panen hanya 8–9 bulan setelah tanam — lalu berproduksi terus setiap minggu sepanjang tahun. Buahnya digemari untuk buah potong, jus, kolak, dan lalapan, sementara daun dan getahnya pun bernilai untuk olahan dan bumbu. Pepaya cocok ditanam di pekarangan atau lahan tepi dengan pakan pupuk organik yang rutin, dan buah pekat manis dari petani lokal selalu lebih diminati pasar daripada buah unggul import.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/287585c9b8b3.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/287585c9b8b3.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/f21519328c87.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4a87ea7fb936.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ef58ed7e0950.jpg"]', '["Semai benih dari buah matang sehat di polybag kecil selama 4–6 minggu.", "Olah lubang 50×50 cm dengan pupuk kandang; pilih lokasi tanah gembur drainase baik.", "Tanam bibit dengan pilihan: 3 bibit per lubang lalu sisakan jantan/betina sesuai kebutuhan, atau gunakan bibit berkelamin betina/hermafrodit.", "Panen buah pertama usia 8–10 bulan saat kulit mulai menguning di bagian bawah buah."]', '["Pupuk kandang 2 bulanan dan abu gosok untuk buah manis pekat dengan aroma kuat.", "Jaga jarak tanam 2×2 m dan pangkas daun tua agar tajuk terbuka dan mudah dipanen.", "Hindari genangan air — akar pepaya sangat sensitif busuk; buat saluran di sekeliling pohon.", "Panen dengan memutar perlahan, jangan tarik; simpan di tempat teduh sebelum dijual."]', '[{"name": "Virus Curl (Virus Keriting)", "symptom": "Daun muda keriting, menggulung ke atas, dan berwarna hijau pucat.", "treatment": "Kendalikan kutu putih vektor dengan perangkap kuning; cabut tanaman terinfeksi."}, {"name": "Busuk Akar & Pangkal", "symptom": "Daun menguning, pohon roboh, pangkal batang lembek berair.", "treatment": "Drainase baik, aplikasi Trichoderma, tanam di guludan tinggi."}, {"name": "Kutu Putih", "symptom": "Serangga putih kecil menempel rapi di balik daun; daun menguning perlahan.", "treatment": "Perangkap kuning, semprotkan sabun kalium atau minyak nimba."}]', 'Rp 5.000 – 12.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('jeruk', 'Jeruk Siam / Keprok', 'Citrus nobilis', 'buah', 'sedang', 730, 'sedang', 'terang penuh', 'Panen utama musim kering akhir (Agustus–Oktober)', 'Jeruk siam dan keprok adalah buah komersial bernilai tinggi yang diminati sepanjang tahun, dengan puncak harga saat hari raya. Meski panen pertama menunggu sekitar 2 tahun, jeruk membalas dengan produksi puluhan tahun dan pemasukan musiman besar setiap panen raya. Bibit jeruk bersertifikat dari kebun bibit resmi adalah kunci: sehat, tidak virus, dan cepat berbuah dengan rasa manis pekat yang khas jeruk Kutai.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ac1aac0cb1fd.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ac1aac0cb1fd.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/62fcd243628e.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0e674a99213f.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/fb6abb05ea0b.jpg"]', '["Beli bibit jeruk bersertifikat umur 6–12 bulan dari kebun bibit resmi tanpa gejala kuning (CVPD).", "Buat lubang 60×60×60 cm jarak tanam 6×6 m; campurkan pupuk kandang dan dolomit.", "Tanam bibit dengan kerah (pangkal batang) di atas permukaan tanah, buat cekungan penampung air.", "Panen buah saat kulit menguning cerah dan rasa manis tercapai; gunakan gunting jeruk dengan tangkai pendek."]', '["Pemupukan NPK seimbang 3–4 kali setahun plus pupuk organik untuk rasa buah manis.", "Pangkas cabang kering, tumbuh ke dalam, dan tunas air agar cahaya menembus seluruh tajuk.", "Awas penyakit kuning CVPD (vektornya kutu Diaphorina) — inspeksi daun muda rutin dan semprot nimba.", "Beri mulsa jerami di sekitar pohon untuk menjaga kelembapan dan menekan gulma musim kering."]', '[{"name": "CVPD (Penyakit Kuning)", "symptom": "Daun belang kuning tidak simetris, buah kecil asam miring, cabang mati bertahap.", "treatment": "Bibit sehat bersertifikat, kendalikan kutu vektor, musnahkan pohon sakit."}, {"name": "Kutu Busuk (Planococcus)", "symptom": "Serangga putih berbulu di buah dan tunas dengan madu hitam (sooty mold).", "treatment": "Semprotkan minyak nimba, perkuat semut rangrang predator alami."}, {"name": "Keriting Daun (Psylla)", "symptom": "Daun muda menggulung dan keriting; tunas tidak berkembang.", "treatment": "Semprotkan insektisida hayati saat tunas muda muncul, jaga kesehatan pohon."}]', 'Rp 15.000 – 35.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('semangka', 'Semangka', 'Citrullus lanatus', 'buah', 'sedang', 75, 'sedang', 'terang penuh', 'Musim kemarau (harga terbaik)', 'Semangka adalah buah musiman bernilai jual besar — satu hektar lahan semangka musim kemarau bisa memberi pendapatan yang jauh melebihi padi. Tanaman merambat ini paling produktif di musim kering dengan irigasi terkontrol, dan harganya melonjak saat pasokan turun. Dengan mulsa plastik dan pupuk terjadwal, panen pertama bisa dipungut hanya 70–80 hari setelah tanam, sehingga cocok sebagai tanaman musim ke-2 setelah padi.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/84bb3ab8fb17.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/84bb3ab8fb17.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/1ec01cfea73e.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/ba9ef1bbe239.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/d6abe05c3310.jpg"]', '["Buat guludan lebar 2–2,5 m dengan mulsa plastik hitam, tanam benih/bibit hibrida jarak 60 cm.", "Tanam 1–2 benih per lubang kedalaman 2 cm, siram hingga berkecambah 4–6 hari.", "Arahkan pucuk rambatan ke arah berlawanan antar baris; lubangi mulsa untuk buah yang mau tumbuh.", "Panen saat kulit mengilap, garis tanda puncak menonjol, dan sulur di dekat tangkai mengering (usia 70–85 hari)."]', '["Air terkontrol: cukup dan merata saat berbuah, dikurangi 1 minggu sebelum panen agar manis pekat.", "Pupuk dominan kalium saat buah berukuran telur untuk kadar gula tinggi dan rasa renyah.", "Sisakan 1–2 buah per tanaman untuk buah besar seragam; buah pertama yang terbaik sebaiknya dipertahankan.", "Balik buah setiap 5–7 hari agar warna kulit merata dan tidak busuk karena menempel tanah."]', '[{"name": "Virus Daun Belang", "symptom": "Daun keriting belang kuning-hijau, tanaman kerdil dan buah sedikit.", "treatment": "Kendalikan kutu daun vektor, cabut tanaman sakit, gunakan benih hibrida tahan virus."}, {"name": "Busuk Buah", "symptom": "Bagian buah menempel tanah membusuk berair lalu menghitam.", "treatment": "Balik buah rutin, beri alas jerami di bawah buah, jaga drainase guludan."}, {"name": "Antraknosa", "symptom": "Bercak cekung gelap dengan bintik jingga pada daun dan buah.", "treatment": "Fungisida tembaga, mulsa plastik, jauhkan daun dari kontak tanah."}]', 'Rp 6.000 – 15.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('bawang-putih', 'Bawang Putih', 'Allium sativum', 'bumbu-dapur', 'sulit', 90, 'sedikit', 'terang penuh', 'Musim kering sejuk (Juni–September)', 'Bawang putih adalah bumbu inti hampir semua masakan Indonesia — digoreng, ditumbuk, hingga dijadikan bawang putih goreng siap pakai yang selalu laku. Pasokan nasional masih bergantung impor, sehingga bawang putih lokal dengan aroma tajam kuat sangat dicari dan harganya premium. Budidayanya menuntut musim kering sejuk dengan air terkontrol, namun panen pertama yang berhasil memberi harga jual jauh di atas bawang merah.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a17aa7a9d47a.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a17aa7a9d47a.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cd4b4998ceb5.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/bca665e14d98.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0b44fa0c5b59.jpg"]', '["Pilih siung bawang putih lokal berukuran besar dan padat, pecahkan sehari sebelum tanam.", "Buat bedengan tinggi 25–30 cm yang gembur dan drainase baik pada musim kering.", "Tanam siung dengan ujung menghadap ke atas, terbenam 2/3 bagian, jarak 10×15 cm.", "Panen saat 70–80% daun menguning dan meroboh (usia 85–95 hari); angkat bersama umbi, jemur 5–7 hari."]', '["Air sangat terkontrol: cukup lembap saja — terlalu basah membuat umbi busuk dan tidak beraroma tajam.", "Pupuk dasar kandang matang dan sedikit NPK; berlebih nitrogen membuat daun rimbun tetapi umbi kecil.", "Rutin penyiangan karena bawang putih tumbuh lambat dan mudah kalah oleh gulma.", "Setelah panen, jemur hingga kulit kertas dan simpul akar kering agar tahan simpan 4–6 bulan."]', '[{"name": "Busuk Putih", "symptom": "Pangkal umbi ditumbuhi jamur putih kapas dan membusuk.", "treatment": "Aplikasi Trichoderma ke bedengan, rotasi tanaman dengan palawija."}, {"name": "Thrips", "symptom": "Garis putih keperakan pada daun, pertumbuhan terhambat.", "treatment": "Perangkap biru, semprotan sabun kalium, jaga kelembapan tanah."}, {"name": "Bercak Ungu", "symptom": "Bercak cokelat keunguan dengan lingkaran konsentris pada daun.", "treatment": "Fungisida difenokonazol, jarak tanam cukup agar sirkulasi baik."}]', 'Rp 35.000 – 60.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('cabai-rawit', 'Cabai Rawit', 'Capsicum frutescens', 'bumbu-dapur', 'sedang', 80, 'sedang', 'terang penuh', 'Sepanjang tahun, harga terbaik musim hujan', 'Cabai rawit adalah bumbu wajib sambal — kebutuhan harian yang tidak bisa digantikan, membuat permintaannya selalu stabil bahkan melonjak saat mendekati hari raya. Tanaman rawit lebih tahan hama dan penyakit dibanding cabai merah besar, berumur lebih panjang hingga 1–2 tahun, dan terus berbuah mingguan. Untuk petani pekarangan, sepuluh pohon rawit saja sudah cukup untuk kebutuhan dapur sekaligus jualan ikatan ke tetangga.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d3574041db0.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5d3574041db0.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/fd60a851b9f1.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cd13efeb2994.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c8d209cf5109.jpeg"]', '["Semai benih di tray semai 3–4 minggu hingga bibit berdaun 4–5 helai.", "Tanam di bedengan/polybag jarak 50×60 cm dengan pupuk kandang dasar yang matang.", "Siram larutan Trichoderma saat pindah tanam untuk cegah layu; beri mulsa jerami/plastik.", "Panen pertama usia 75–85 hari; petik bersama tangkai saat buah merah penuh atau hijau segar sesuai pasar."]', '["Panen setiap 5–7 hari agar pohon terus berbuah; rawit panen bersambung hingga 1–2 tahun.", "Pupuk NPK susulan setiap 10 hari; tambah kalium saat musim berbuah lebat.", "Perangkap kuning untuk kutu daun dan thrips; semprotkan nimba secara berkala.", "Pangkas cabang tua dan ranting kering setiap 2–3 bulan untuk memperbarui rumpun produksi."]', '[{"name": "Kuning Cikur (Phytophthora)", "symptom": "Daun menguning dari ujung cabang, tanaman mati bertahap dalam 2–3 pekan.", "treatment": "Trichoderma rutin, drainase baik, hindari tanah bekas cabai sakit tahun lalu."}, {"name": "Antraknosa", "symptom": "Bercak cekung cokelat gelap pada buah, terutama saat hujan lembap.", "treatment": "Fungisida tembaga/klorotalonil, panen tepat waktu, mulsa plastik."}, {"name": "Kutu Daun", "symptom": "Daun muda keriting lengket berkoloni serangga hijau kecil.", "treatment": "Semprotkan sabun kalium, perangkap kuning, imunomutur+fungisida hayati."}]', 'Rp 40.000 – 120.000 / kg (fluktuatif)')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('jahe', 'Jahe', 'Zingiber officinale', 'bumbu-dapur', 'sedang', 270, 'sedang', 'teduh sebagian', 'Sepanjang tahun (panen 9–12 bulan)', 'Jahe adalah rimpang bumbu sekaligus ramuan — dari wedang jahe, jamu, minuman herbal kekinian, hingga industri olahan eksport kering dan minyak atsiri. Jenis jahe gajah besar dim pasar dapur, sementara jahe emprit dan merah bernilai tinggi untuk jamu dan ekspor. Tanaman ini perawatannya santai (tidak perlu air harian), tahan di bawah pepohonan, dan harga rimpang segar selalu menguntungkan karena permintaan herbal nasional terus naik.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/28a0b1732a65.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/28a0b1732a65.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/91d3d61b5712.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0cec58fc83ca.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4a4a12dae3cd.jpg"]', '["Pilih rimpang bibit segar berbintik mata tunas banyak, potong 2–3 mata per bibit.", "Rekatkan ( rendam ) bibit dengan agens hayati Trichoderma, jemur keringkan sebagian lalu simpan 1–2 hari agar luka kering.", "Buat guludan atau lubang jarak 40×40 cm, tanam bibit kedalaman 5–8 cm dengan tunas menghadap atas.", "Panen rimpang pada usia 9–12 bulan saat daun mengering; gali hati-hati agar rimpang tidak patah."]', '["Mulsa jerami atau daun kering tebal 5 cm menjaga kelembapan dan menekan gulma.", "Pupuk kandang saat tanam dan pupuk kalium saat bulan ke-4 untuk pembesaran rimpang.", "Hindari lahan tergenang — jahe paling rentan layu basah; pilih tanah gembur berdrainase baik.", "Panen parsial: ambil sebagian rimpang tua di pinggir gunung (lumbung biarkan tumbuh lanjut)."]', '[{"name": "Layu Bakteri (Ralstonia)", "symptom": "Tanaman layu cepat, pangkal batang berair, rimpang busuk bau.", "treatment": "Rotasi tanaman lama, Trichoderma, musnahkan tanaman sakit beserta rimpangnya."}, {"name": "Busuk Rimpang (Pythium)", "symptom": "Rimpang membusuk kehitaman di musim hujan tanah tergenang.", "treatment": "Drainase baik, guludan tinggi, aplikasi agens hayati sebelum tanam."}, {"name": "Ulat Daun", "symptom": "Daun berlubang; larva hijau memakan bagian daun muda.", "treatment": "Rakit manual atau semprotkan Bt saat populasi naik."}]', 'Rp 25.000 – 50.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kunyit', 'Kunyit', 'Curcuma longa', 'bumbu-dapur', 'mudah', 270, 'sedang', 'teduh sebagian', 'Sepanjang tahun (panen 9–12 bulan)', 'Kunyit adalah bumbu kuning wajib untuk kuning, gulai, nasi, dan berbagai jamu, sekaligus bahan kunyit asam yang diminati semua kalangan. Dibanding jahe, kunyit lebih mudah tumbuh di berbagai tanah dan lebih tahan kondisi kurang ideal. Warna kunyit pekat dari petani lokal lebih dicari pasar jamu dan dapur rumah tangga, dan rimpangnya tahan simpan lama sehingga bisa menunggu harga terbaik sebelum dijual.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/eb79024951d9.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/eb79024951d9.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/65aebc82fe4e.jpeg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/a476b2d6c9d9.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/2b3f7e0a81ae.jpg"]', '["Pilih rimpang bibit segar dari panen sehat; potong 2–3 mata tunas per bibit.", "Buat guludan atau lubang jarak 40×40 cm, campurkan pupuk kandang matang di lubang.", "Tanam bibit kedalaman 5–8 cm, tutup tanah halus dan beri mulsa jerami.", "Panen pada usia 9–12 bulan saat daun mulai kering; gali seluruh rumpun rimpang."]', '["Mulsa tebal menyuplai kelembapan sekaligus gulma; kunyit minim rawat di musim tumbuh.", "Pupuk kandang saat tanam dan NPK seimbang saat bulan ke-3–4 untuk warna rimpang pekat.", "Bisa dipanen sebagian (ambil rimpang bawah) dan biarkan anak rimpang terus tumbuh.", "Cuci rimpang panen, jemur sebentar, simpan di gudang teduh — kunyit tahan 2–3 bulan segar."]', '[{"name": "Busuk Rimpang", "symptom": "Rimpang kecokelatan basah dan busuk saat tanah terlalu lembap.", "treatment": "Drainase baik, jangan tanam di tanah bekas kunyit/ jahe sakit, Trichoderma."}, {"name": "Bercak Daun", "symptom": "Bercak cokelat besar pada daun tua menyebar saat musim hujan.", "treatment": "Buang daun sakit, jaga sirkulasi, semprotkan fungisida tembaga bila berat."}, {"name": "Ulat Daun", "symptom": "Larva hijau memakan daun hingga berlubang-lelubang.", "treatment": "Rakit manual atau Bt; biasanya tidak sampai merugikan hasil."}]', 'Rp 18.000 – 35.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('lengkuas', 'Lengkuas / Laos', 'Alpinia galanga', 'bumbu-dapur', 'mudah', 300, 'sedang', 'teduh sebagian', 'Sepanjang tahun', 'Lengkuas adalah bumbu rempah khas untuk rendang, gulai, dan semua masakan berkuah santan — aromanya tidak tergantikan oleh bumbu lain. Tanaman ini termasuk paling mudah: ditanam sekali, rumpunnya terus membesar, dan petani bisa memanen potongan rimpang sesuai kebutuhan tanpa mencabut seluruh tanaman. Cocok ditanam di tepi kebun, pekarangan, atau bawah pepohonan sebagai tanaman sambilan yang tetap memberi penghasilan.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/129f77d10f07.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/129f77d10f07.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b1c1fbac5804.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/f3ec046e22fc.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/4bcddc106bf6.jpg"]', '["Pilih rimpang bibit segar berbanyak tunas, potong 2–3 mata per bibit, keringkan permukaan potongan 1 hari.", "Buat lubang 40×40 cm jarak 50×50 cm di tanah gembur dengan pupuk kandang dasar.", "Tanam bibit kedalaman 5–10 cm, tunas menghadap atas, tutup mulsa jerami.", "Panen rimpang tua mulai usia 10–12 bulan; gali sebagian dari tepi rumpun tanpa mencabut induk."]', '["Rumpun lengkuas membesar setiap tahun — pisahkan dan pindahkan anakan untuk memperluas kebun.", "Pupuk kandang setiap 6 bulan cukup; lengkuas sangat minim kebutuhan perawatan.", "Jaga tanah lembap di musim kering dengan mulsa, tetapi hindari genangan.", "Potong batang tua dan daun kering agar rumpun terbuka dan mudah dipanen."]', '[{"name": "Busuk Rimpang", "symptom": "Rimpang bagian dalam menghitam berair dan busuk.", "treatment": "Drainase baik, rotasi lokasi, Trichoderma pada guludan."}, {"name": "Ulat Daun", "symptom": "Daun berlubang oleh larva hijau-cokelat.", "treatment": "Rakit manual, semprotkan Bt bila ramai."}, {"name": "Bercak Daun", "symptom": "Bercak cokelat memanjang pada daun tua.", "treatment": "Pangkas dan buang daun sakit; umumnya tidak memerlukan fungisida."}]', 'Rp 15.000 – 30.000 / kg')
on conflict (slug) do nothing;
insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kencur', 'Kencur', 'Kaempferia galanga', 'bumbu-dapur', 'mudah', 240, 'sedikit', 'teduh sebagian', 'Sepanjang tahun (panen 8–10 bulan)', 'Kencur adalah bumbu aroma khas untuk berburu (nasi kencur), jamu beras kencur, dan berbagai ramuan tradisional — pasarnya stabil dari industri jamu hingga warung makan. Tanaman kecil rendah ini tidak butuh lahan luas: cukup pekarangan atau polybag besar yang teduh sebagian. Kencur juga tahan kering, minim hama, dan bisa dipanen sesuai kebutuhan sehingga sangat cocok bagi petani pemula yang ingin mencoba tanaman rempah.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cd1b41c15be7.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cd1b41c15be7.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c5cdeabec32d.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/0f16ad3cc2f7.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/d8233c80162a.png"]', '["Pilih rimpang bibit segar berpembengkakan padat, siapkan potongan 1–2 mata tunas.", "Buat guludan atau polybag besar dengan campuran tanah gembur dan pupuk kandang.", "Tanam bibit kedalaman 3–5 cm jarak 20×20 cm, tunas menghadap atas, tutup mulsa tipis.", "Panen pada usia 8–10 bulan saat daun mulai mengering; gali seluruh rumpun rimpang."]', '["Siram hanya saat tanah benar-benar kering; kencur tahan kering lebih baik daripada terlalu basah.", "Pupuk kandang saat tanam cukup; tambah sedikit NPK saat bulan ke-2 untuk daun lebat.", "Teduh sebagian (50–60% cahaya) membuat rimpang lebih besar dan aromanya lebih tajam.", "Simpan panen di tempat sejuk teduh; kencur segar dengan aroma kuat selalu dicari penjual jamu."]', '[{"name": "Busuk Rimpang", "symptom": "Rimpang membusuk berair saat tanah terlalu lembap lama.", "treatment": "Drainase baik, kurangi siram, Trichoderma pada media tanam."}, {"name": "Bercak Daun", "symptom": "Bercak cokelat membulat pada daun lebar kencur.", "treatment": "Buang daun sakit, jaga sirkulasi; jarang butuh fungisida kimia."}, {"name": "Kutu Akar", "symptom": "Rimpang berlubang kecil dengan serangga putih kecil di dalam tanah.", "treatment": "Rotasi tanaman, aplikasi Metarhizium atau kapur pertanian ke tanah."}]', 'Rp 45.000 – 80.000 / kg')
