insert into public.crops (slug, name, latin_name, category, difficulty, harvest_days, water_need, sun_need, season, description, image_url, gallery, planting_steps, care_tips, diseases, price_range)
values ('kemangi', 'Kemangi', 'Ocimum basilicum', 'bumbu-dapur', 'mudah', 45, 'sedang', 'terang', 'Sepanjang tahun', 'Kemangi adalah lalapan daun wajib pelengkap ikan bakar, ayam goreng, pecel lele, dan semua menu rakyat — ikatan kecilnya selalu laku di pasar dan warung. Tanaman asli Indonesia ini sangat mudah tumbuh: dari benih maupun stek batang, cepat panen 4–6 minggu, dan bisa dipotong berulang hingga 4–5 kali. Aroma kemangi segar langsung dari kebun petani jauh lebih kuat daripada yang dijual gerobak berjam-jam, menjadikan nilai jualnya menarik.', 'https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c8423dc06d1b.jpg', '["https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/c8423dc06d1b.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/43f8af52c2ec.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/532136399393.jpg", "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/566dc69afa7d.jpg"]', '["Tabur benih di polybag atau bedengan tipis, tutup sangat tipis dengan tanah halus.", "Jaga lembap hingga berkecambah 4–7 hari; kemangi kecil-kecil tumbuh rumpun.", "Pindah tanam atau tipiskan dengan jarak 20×20 cm saat berdaun 4–6 helai.", "Panen pucuk muda mulai usia 4–6 minggu: potong ujung rumpun agar bercabang lebat."]', '["Panen dengan memotong ujung pucuk (bukan mencabut) agar rumpun tumbuh semakin lebat.", "Siram pagi hari; kemangi tidak tahan tanah tergenang tapi juga mudah layu saat kering ekstrem.", "Pupuk organik cair setiap 2 pekan untuk daun hijau pekat dengan aroma kuat.", "Awas ulat hijau dan kutu daun; semprotan nimba tipis rutin menjaga daun tetap bersih untuk lalapan."]', '[{"name": "Layu Bakteri", "symptom": "Rumpun layu cepat tanpa menguning; pangkal batang kecokelatan.", "treatment": "Drainase baik, rotasi media, Trichoderma; cabut tanaman sakit."}, {"name": "Kutu Daun", "symptom": "Daun muda keriting dengan koloni serangga hijau kecil.", "treatment": "Semprotan air sabun kalium tipis; cuci daun sebelum dijual."}, {"name": "Busuk Daun", "symptom": "Daun basah kecokelatan saat cuaca lembap terus.", "treatment": "Jaga sirkulasi, siram pagi saja agar daun kering sebelum malam."}]', 'Rp 2.000 – 5.000 / ikat')
